window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["anki:ginecologia-ciclo-menstrual"]={"block":"anki:ginecologia-ciclo-menstrual","label":"Anki · Ciclo Menstrual","count":50,"questions":[{"id":"anki-ginecologia-ciclo-menstrual-e1bcc0bfefe4ba9d","number":"0201b","sourceNumber":"0201b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Em uma mulher com deficiência de aromatase, a metabolização que está comprometida é:","options":{"A":"conversão de colesterol em androstenediona.","B":"conversão de androstenediona em estradiol.","C":"conversão de colesterol em estradiol.","D":"conversão de androstenediona em progesterona."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟡 Média\n\nEixos: Endocrinologia, Metabolismo de Esteroides, Deficiência de Aromatase.\n\nResumo Essencial\n\nAromatase: Enzima crucial para converter andrógenos (androstenediona/testosterona) em estrógenos (estrona/estradiol).\n\nDeficiência de aromatase: Acúmulo de andrógenos e deficiência de estradiol, causando hiperandrogenismo e hipoestrogenismo.\n\nCorreção Direta e Estruturada\n✅ Resposta correta:\n\nConversão de androstenediona em estradiol:\n\nAromatase transforma:\n\nAndrostenediona → Estrona (E1).\n\nTestosterona → Estradiol (E2).\n\n❌ Erros nas alternativas incorretas:\n\nConversão de androstenediona em progesterona: Enzima 3β-hidroxiesteroide desidrogenase.\n\nConversão de colesterol em androstenediona: Via P450scc (clivagem da cadeia lateral do colesterol).\n\nConversão de colesterol em estradiol: Não ocorre diretamente (requer androstenediona como intermediário).\n\nVia Metabólica dos Esteroides\n\nColesterol → Pregnenolona (P450scc).\n\nPregnenolona → Progesterona ou Androstenediona (via Δ4 ou Δ5).\n\nAndrostenediona →:\n\nTestosterona (17β-hidroxiesteroide desidrogenase).\n\nEstrona (aromatase).\n\nPor que os alunos erram?\n\nConfundem aromatase com outras enzimas (ex.: 5α-redutase).\n\nIgnoram que a aromatase atua apenas na última etapa (andrógeno → estrógeno).\n\nRecurso Extra\n💡 Comparação:\n\n\"A aromatase é como um tradutor que converte a 'linguagem' dos andrógenos (masculina) em estrógenos (feminina).\"","tags":["#Aromatase","#Endocrinologia","#Esteroides","#Estradiol","#MetabolismoHormonal","Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766766","ankiGuid":"I!R(Ej}dL4"},{"id":"anki-ginecologia-ciclo-menstrual-e09830142996d92d","number":"0202b","sourceNumber":"0202b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Na fase luteínica média de um ciclo menstrual normal, podemos afirmar que a:","options":{"A":"Progesterona está baixa, o muco cervical tem filância intensa e o endométrio será secretório.","B":"Progesterona está alta, o muco cervical está com a cristalização em grumos e o corpo lúteo deve estar presente.","C":"Progesterona se encontra em níveis semelhantes ao verificado durante a menstruaçãoe o muco cervical se cristaliza, formando ramificações secundárias e terciárias.","D":"Progesterona deve estar elevada, o endométrio será proliferativo misto e o mucocervical abundante."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"Nível: 🟡 Média\nCobra fisiologia do ciclo menstrual: fase lútea, progesterona, muco cervical e endométrio.\n\nResumo essencial\n\nNa fase luteínica média, há corpo lúteo ativo produzindo progesterona alta. Isso deixa o endométrio secretório e o muco cervical espesso, pouco filante e em grumos.\n\nCorreção direta\n\n✅ Progesterona alta + muco em grumos + corpo lúteo presente\n\nCorreta → após ovulação, o corpo lúteo secreta progesterona, que prepara o endométrio para implantação e torna o muco cervical hostil à passagem espermática.\n\nErros principais das incorretas\n\n❌ Progesterona baixa: errado → na fase lútea ela está elevada.\n❌ Filância intensa: é efeito estrogênico, típico do período periovulatório.\n❌ Endométrio proliferativo: é da fase folicular; na lútea é secretório.\n❌ Muco com arborização/“samambaia”: ocorre com estrogênio alto, antes da ovulação.\n\nFisiologia-chave\n\nEstrogênio → muco claro, abundante, filante, cristalização em samambaia\n\nProgesterona → muco espesso, opaco, grumoso, pouca filância\n\nFase lútea média → progesterona máxima\n\n💡 Macete\nProgesterona “fecha a porta”: muco grosso, endométrio secretório e corpo lúteo funcionando.\n\nGlossário\n\nCorpo lúteo: estrutura pós-ovulatória produtora de progesterona.\n\nFilância: capacidade do muco cervical formar fio.\n\nCristalização em samambaia: padrão estrogênico do muco cervical.","tags":["#CicloMenstrual","#Endométrio","#FaseLútea","#Ginecologia","#MucoCervical","#Progesterona","Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766767","ankiGuid":"dDoa&pspa7"},{"id":"anki-ginecologia-ciclo-menstrual-3d7b97ba28c1bcf9","number":"0203b","sourceNumber":"0203b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Em um ciclo menstrual normal a sequência esperada é:","options":{"A":"Pico do estradiol – pico do LH – ovulação.","B":"Pico de LH –pico de estradiol – ovulação.","C":"Pico de LH – ovulação – pico do estradiol.","D":"Pico de estradiol – pico de progesterona – ovulação."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"Nível: 🟡 Média\nCobra sequência hormonal do ciclo menstrual (eixo HHO).\n\nResumo essencial\n\nO estradiol sobe primeiro, desencadeia feedback positivo → pico de LH, que induz a ovulação.\n\nCorreção direta\n\n✅ Pico de estradiol → pico de LH → ovulação\n\nEstradiol alto por ~48h → feedback positivo no hipotálamo/hipófise\n→ surto de LH → ruptura folicular (ovulação em ~36h)\n\nErros principais das incorretas\n\n❌ LH antes do estradiol: inverte a fisiologia (LH é consequência do E2 alto).\n❌ Estradiol depois do LH: errado → E2 precede o pico de LH.\n❌ Progesterona antes da ovulação: incorreto → sobe após a ovulação (fase lútea).\n\nFisiologia-chave\n\nFolicular tardia: ↑ estradiol sustentado\n\nTransição: E2 alto → pico de LH\n\nEvento: LH → ovulação (24–36h)\n\nLútea: ↑ progesterona (corpo lúteo)\n\n💡 Macete\n“E2 chama LH, LH faz ovular”\n\nGlossário\n\nEstradiol (E2): principal estrogênio ovariano\n\nLH: hormônio que desencadeia a ovulação\n\nOvulação: liberação do oócito do folículo dominante","tags":["#CicloMenstrual","#Estradiol","#Ginecologia","#LH","#Ovulação","Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766768","ankiGuid":"nE5d_uA97k"},{"id":"anki-ginecologia-ciclo-menstrual-977d3826436b42e3","number":"0204b","sourceNumber":"0204b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"O endométrio que não é encontrado em um ciclo menstrual monofásico é:","options":{"A":"Hiperplásico.","B":"Atrófico.","C":"Proliferativo.","D":"Secretório."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"Nível: 🟡 Média\nCobra ciclo menstrual anovulatório (monofásico) + resposta endometrial.\n\nResumo essencial\n\nCiclo monofásico = sem ovulação → sem progesterona → não há fase lútea\n→ logo, não existe endométrio secretório.\n\nCorreção direta\n\n✅ Endométrio secretório (NÃO encontrado)\n\nRequer progesterona do corpo lúteo\n\nComo não há ovulação → não há corpo lúteo → não há secreção progesterônica\n\nErros principais das incorretas\n\n❌ Proliferativo: presente → estímulo estrogênico contínuo.\n❌ Atrófico: pode ocorrer em contextos hipoestrogênicos.\n❌ Hiperplásico: pode ocorrer por estrogênio sem oposição.\n\nFisiopatologia-chave\n\nCiclo monofásico (anovulatório):\n\nEstrogênio isolado → proliferação contínua\n\nAusência de progesterona → sem transformação secretora\n→ risco de hiperplasia endometrial\n\n💡 Macete\n“Sem ovulação, sem progesterona, sem secreção”\n\nGlossário\n\nMonofásico: ciclo sem fase lútea\n\nEndométrio secretório: fase pós-ovulatória dependente de progesterona\n\nHiperplasia endometrial: proliferação excessiva por estrogênio","tags":["#Anovulação","#CicloMenstrual","#Endométrio","#Ginecologia","#ResidênciaMédica","Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766769","ankiGuid":"Cfus7]vkg-"},{"id":"anki-ginecologia-ciclo-menstrual-2b01578b3896725f","number":"0205b","sourceNumber":"0205b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Em relação ao ovário está incorreto:","options":{"A":"As unidades foliculares são constituídas das células granulosas que rodeiam o óvulo e das células tecais que envolvem os primeiros.","B":"De acordo com a teoria das duas células, o estradiol é produzido nas células da teca interna através da conversão da androstenediona proveniente das células da granulosa.","C":"No processo de crescimento folicular, a grande maioria dos folículos se degenera, processo conhecido como atresia folicular.","D":"Tanto o ovário, através do estradiol e progesterona, como o hipotálamo através do GnRH influenciam o volume de secreção hipofisária de gonadotrofinas.","E":"O corpo lúteo produz progesterona."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"Nível: 🟡 Média\nCobra fisiologia ovariana + teoria das duas células (granulosa vs teca).\n\nResumo essencial\n\nNa teoria das duas células, a teca produz andrógenos e a granulosa converte em estradiol.\nA alternativa inverte isso.\n\nCorreção direta\n\n❌ Incorreta: produção de estradiol na teca a partir de androstenediona da granulosa\n\nErrado → o correto é:\n\nTeca interna (LH) → produz andrógenos (androstenediona)\n\nGranulosa (FSH) → aromatiza andrógenos → estradiol\n\nPor que as outras estão corretas\n\n✅ Atresia folicular: maioria dos folículos degenera.\n✅ Estrutura folicular: granulosa + teca.\n✅ Eixo HHO: ovário (E2/progesterona) + GnRH regulam gonadotrofinas.\n✅ Corpo lúteo: principal produtor de progesterona.\n\nFisiopatologia-chave\n\nLH → teca → andrógenos\n\nFSH → granulosa → aromatase → estradiol\n\n→ cooperação obrigatória entre as duas células\n\n💡 Macete\n“Teca faz testosterona, granulosa faz estrogênio”\n\nGlossário\n\nTeca interna: camada produtora de andrógenos\n\nGranulosa: camada com aromatase\n\nAromatização: conversão de andrógeno → estrogênio","tags":["#AtresiaFolicular","#Estradiol","#Fisiologia","#Ovário","#TeoriaDuasCélulas","Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766770","ankiGuid":"B}5O$pf},d"},{"id":"anki-ginecologia-ciclo-menstrual-1b237aac9ae93d4c","number":"0206b","sourceNumber":"0206b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Na fisiologia menstrual:","options":{"A":"O LH determina o pico do estradiol, que tem implicação na ovulação.","B":"No final da primeira fase, o estrogênio atinge o pico e exerce feedback positivo no hipotálamo e na hipófise.","C":"Para ocorrer a ovulação, o LH e o FSH devem estabelecer picos dois dias antes.","D":"Não ocorrendo a fecundação, a descamação endometrial é decorrente da eliminação do óvulo não fecundado e do corpo lúteo."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"Nível: 🟡 Média\nCobra eixo HHO e mecanismos hormonais da ovulação.\n\nResumo essencial\n\nNo final da fase folicular, o estradiol elevado sustentado muda o feedback para positivo, desencadeando o pico de LH → ovulação.\n\nCorreção direta\n\n✅ Estrogênio no pico → feedback positivo → estímulo hipotalâmico-hipofisário\n\nCorreta → estradiol alto por ~48h → ↑ GnRH → surto de LH → ovulação.\n\nErros principais das incorretas\n\n❌ LH e FSH com pico simultâneo 2 dias antes: FSH não tem pico relevante; o principal é o LH e ocorre ~24–36h antes.\n❌ LH determina pico de estradiol: invertido → estradiol alto é que induz o pico de LH.\n❌ Descamação por eliminação do óvulo/corpo lúteo: falso → menstruação ocorre por queda de progesterona/estrogênio (luteólise), não pela “eliminação física”.\n\nFisiopatologia-chave\n\nFolicular tardia: ↑ estradiol sustentado\n→ feedback positivo\n→ pico de LH\n→ ovulação\n→ Lútea: ↑ progesterona (corpo lúteo)\n→ Sem fecundação: luteólise → queda hormonal → menstruação\n\n💡 Macete\n“Estradiol alto vira a chave → dispara o LH”\n\nGlossário\n\nFeedback positivo: estímulo ao invés de inibição hormonal\n\nLH surge: pico de LH que desencadeia ovulação\n\nLuteólise: regressão do corpo lúteo","tags":["#CicloMenstrual","#EndócrinoReprodutivo","#Estradiol","#Fisiologia","#FisiologiaMenstrual","#Ginecologia","#Ovulação","#PicoLH","#Residência","Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766771","ankiGuid":"Ej,mm;.7sd"},{"id":"anki-ginecologia-ciclo-menstrual-694ea6e821417684","number":"0207b","sourceNumber":"0207b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Uma mulher de 22 anos de idade procura atendimento ambulatorial por atraso menstrual de 12 dias. Trouxe Beta-HCG negativo. Considerando os níveis de FSH, LH e estradiol dentro da normalidade e a progesterona abaixo do esperado, podemos afirmar que:","options":{"A":"Essa paciente está muito provavelmente na fase secretória endometrial.","B":"Essa paciente tem corpo lúteo persistente.","C":"Essa paciente não parece ter ovulado neste ciclo.","D":"Essa paciente tem atrofia endometrial.","E":"Essa paciente provavelmente faz uso de anticoncepcional combinado."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"Nível: 🟡 Média\nCobra anovulação funcional + interpretação de progesterona na fase lútea.\n\nResumo essencial\n\nApós ovulação, o corpo lúteo produz progesterona. Se há atraso menstrual, beta-HCG negativo e progesterona baixa, o ciclo provavelmente foi anovulatório.\n\nCorreção direta\n\n✅ Essa paciente não parece ter ovulado neste ciclo\n\nSem ovulação → não há corpo lúteo funcional → progesterona permanece baixa.\n\nFSH, LH e estradiol normais não excluem anovulação pontual.\n\nErros principais das incorretas\n\n❌ Fase secretória: depende de progesterona alta, não baixa.\n❌ Corpo lúteo persistente: cursaria com progesterona mantida/elevada.\n❌ Uso de anticoncepcional combinado: tenderia a suprimir FSH/LH.\n❌ Atrofia endometrial: esperaria baixo estímulo estrogênico, não estradiol normal.\n\nFisiologia-chave\n\nOvulação → corpo lúteo → progesterona alta → endométrio secretório\nSem ovulação → sem corpo lúteo → progesterona baixa → atraso/irregularidade menstrual\n\n💡 Macete\nProgesterona é o “comprovante” da ovulação.\n\nGlossário\n\nAnovulação: ciclo sem liberação do oócito.\n\nCorpo lúteo: estrutura pós-ovulatória produtora de progesterona.\n\nFase secretória: fase endometrial dependente de progesterona.","tags":["#Anovulação","#AtrasoMenstrual","#CicloMenstrual","#EndocrinologiaGinecológica","#Progesterona","Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766772","ankiGuid":"MfJ(_k>7qV"},{"id":"anki-ginecologia-ciclo-menstrual-233fba23906e69b6","number":"0208b","sourceNumber":"0208b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"A biossíntese do estrogênio exige a ação combinada de duas gonadotrofinas sobre dois tipos de células. Esse conceito é conhecido como teoria das duas células na esteroidogênese ovariana. Marque a opção correta sobre a biossíntese do estrogênio:","options":{"A":"Em resposta à estimulação do FSH, as células tecais sintetizam androgênios, androstenediona e testosterona que se difundem para as células da granulosa que expressam níveis elevados de atividade 21-hidroxilase em resposta à estimulação do LH, convertendo androgênios principalmente em estradiol.","B":"Em resposta à estimulação do TSH, as células da granulosa sintetizam androgênios, androstenediona e diidrotestosterona que se difundem para as células da teca que expressam níveis elevados de 3B-ol-deidrogenase em resposta à estimulação do LH, convertendo androgênios principalmente em estrona.","C":"Em resposta à estimulação do FSH, as células tecais sintetizam estrogênios, estradiol e estrona que se difundem para as células da granulosa que expressam níveis elevados de atividade da aromatase em resposta à estimulação do LH, convertendo estrogênios principalmente em testosterona.","D":"Em resposta à estimulação do LH, as células da granulosa sintetizam estrogênios, estriol e estrona que se difundem para as células da teca que expressam níveis elevados de atividade da 21-hidroxilase em resposta à estimulação do TSH, convertendo estrogênios em progesterona.","E":"Em resposta à estimulação do LH, as células tecais sintetizam androgênios, androstenediona e testosterona que se difundem para as células da granulosa que expressam níveis elevados de atividade da aromatase em resposta à estimulação do FSH, convertendo androgênios principalmente em estradiol."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"Nível: 🟡 Média\nCobra esteroidogênese ovariana e a clássica teoria das duas células/duas gonadotrofinas.\n\nResumo essencial\n\nNa biossíntese do estrogênio: LH estimula a teca a produzir androgênios; depois o FSH estimula a granulosa a aromatizar esses androgênios em estradiol.\n\nCorreção direta\n\n✅ LH na teca → androgênios; FSH na granulosa → aromatase → estradiol\n\nCorreta → a teca interna produz androstenediona/testosterona sob ação do LH.\n\nEsses androgênios difundem-se para a granulosa, onde a aromatase, estimulada pelo FSH, converte em estradiol.\n\nErros principais das incorretas\n\n❌ FSH estimulando teca: errado → teca responde principalmente ao LH.\n❌ LH estimulando aromatase na granulosa: errado → quem induz aromatase é o FSH.\n❌ TSH na esteroidogênese ovariana: não participa desse eixo.\n❌ 21-hidroxilase: enzima adrenal, não a chave para produção ovariana de estradiol.\n❌ Granulosa produzindo androgênios primários: errado → ela converte androgênios em estrogênios.\n\nFisiologia-chave\n\nLH → teca → androstenediona/testosterona → granulosa\nFSH → granulosa → aromatase → estradiol\n\n💡 Macete\n“LH = Lado de fora”: age na teca, que fica mais externa.\n“FSH = Faz Secreção de Hormônio feminino”: granulosa faz estradiol via aromatase.\n\nGlossário\n\nTeca interna: célula ovariana produtora de androgênios.\n\nGranulosa: célula ovariana com aromatase.\n\nAromatase: enzima que converte androgênios em estrogênios.","tags":["#CicloMenstrual","#Esteroidogênese","#Estradiol","#Ginecologia","#Ovário","Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766773","ankiGuid":"B7d{r=SPe:"},{"id":"anki-ginecologia-ciclo-menstrual-3725290db32900d4","number":"0209b","sourceNumber":"0209b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Em relação ao crescimento folicular, estão corretas as seguintes alternativas:\n\n1. O crescimento folicular até a fase antral inicial é permanente durante a vida até a menopausa.\n\n2. O hormônio antimulleriano é um marcador da reserva ovariana e está envolvido no aumento do crescimento folicular e, consequente, apoptose.\n\n3. O estímulo com gonadotrofinas é pré-requisito para o desenvolvimento dos folículos antrais iniciais.","options":{"A":"1 e 3.","B":"1 e 2.","C":"2 e 3.","D":"1, 2 e 3.","E":"Somente 1."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"Nível: 🔴 Difícil\n\nTema clássico com ambiguidade conceitual + pegadinha de prova (AMH e FSH-dependência).\n\nResumo essencial\n\nAté fase antral inicial → independente de FSH\n\nApós isso → dependente de FSH\n\nAMH = freio do recrutamento folicular\n\nCorreção direta\n\n✅ Gabarito correto: 1 e 3\n\n✔️ 1 – Correta\n\nCrescimento folicular até fase antral inicial → FSH-independente\n\nProcesso contínuo ao longo da vida reprodutiva\n\n❌ 2 – Incorreta\n\nAMH:\n\nInibe crescimento folicular\n\nReduz ação do FSH\n\nNão aumenta crescimento → atua como regulador negativo\n\nObjetivo fisiológico:\n\nPreservar reserva ovariana\n\n✔️ 3 – Correta (interpretação de prova)\n\n“Pré-requisito para desenvolvimento dos folículos antrais iniciais”\n\n🔴 Interpretação correta:\n\nPara progressão após atingir fase antral inicial → FSH é necessário\n\n❗ Não significa:\n\nque FSH seja necessário para chegar até essa fase\n\nErro clássico\n\n❌ Confundir:\n\nFormação do antral inicial → independente\n\nCrescimento a partir dele → dependente\n\nFisiologia organizada (alto rendimento)\n\n🔹 Fase inicial (independente)\n\nPrimordial → primário → pré-antral → antral inicial\n\nControle: intraovariano + AMH\n\n🔹 Fase tardia (dependente)\n\nAntral inicial → dominante → ovulação\n\nControle: FSH\n\n💡 Macete definitivo\n\n“Até antral → sozinho; depois → FSH entra”\n\nGlossário\n\nAMH: hormônio que freia recrutamento\n\nFolículo antral: presença de antro\n\nAtresia: morte folicular\n\n🎯 Conclusão estratégica\n\n1 = correta\n\n2 = incorreta\n\n3 = correta (interpretação funcional)\n\n👉 Essa é uma das questões mais clássicas de erro em prova.","tags":["#CrescimentoFolicular","#EndocrinologiaReprodutiva","#Gonadotrofinas","#HormônioAntimülleriano","#ReservaOvariana","Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766774","ankiGuid":"NDqXWAARQa"},{"id":"anki-ginecologia-ciclo-menstrual-c0a303c2527c37f8","number":"0210b","sourceNumber":"0210b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Sobre o ciclo menstrual humano, é INCORRETO afirmar:","options":{"A":"A reserva ovariana é determinada ao nascimento e sofre queda constante, mesmo durante períodos fisiológicos de anovulação, como na infância e na gravidez.","B":"O desenvolvimento folicular ovariano é dependente de níveis basais de androgênios.","C":"A segunda divisão meiótica do oócito é completada antes da ovulação, sob efeito do hormônio luteinizante (LH).","D":"A esteroidogênese ovariana consiste em um processo de ação conjunta das células da teca e da granulosa, com ação combinada de LH e FSH.","E":"Os níveis de inibina atingem o ponto máximo no meio da fase lútea e diminuem caso não haja gravidez, permitindo nova elevação do hormônio folículo estimulante (FSH)."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"Nível: 🔴 Difícil\nCobra maturação oocitária + meiose + fisiologia do ciclo ovariano (alta incidência em prova).\n\nResumo essencial\n\nO oócito não completa a meiose II antes da ovulação.\nEle só termina essa divisão se houver fecundação.\n\nCorreção direta\n\n❌ A segunda divisão meiótica é completada antes da ovulação (INCORRETA)\n\nNa ovulação:\n\no oócito está em metáfase II\n\nA meiose II:\n\nsó termina após a fecundação\n\nPor que as outras estão corretas\n\n✅ Reserva ovariana ↓ contínua: ocorre desde o nascimento, mesmo sem ovulação.\n✅ Androgênios no folículo: servem como substrato para estradiol.\n✅ Inibina na fase lútea: ↓ FSH → ao cair, permite novo ciclo.\n✅ Teoria das duas células: teca (LH) + granulosa (FSH).\n\nFisiologia-chave\n\nVida intrauterina:\n\noócito para em prófase I\n\nPuberdade:\n\nLH → retoma meiose I → forma oócito secundário\n\nOvulação:\n\noócito em metáfase II\n\nFecundação:\n\ncompleta meiose II\n\n💡 Macete\n\n“Ovulou em metáfase II, só termina se fecundar”\n\nGlossário\n\nMetáfase II: estágio do oócito ovulado\n\nMeiose II: divisão final do oócito\n\nCorpo lúteo: estrutura pós-ovulatória\n\n🎯 Conclusão estratégica\n\n👉 Sempre que falar de meiose:\n\nAntes da ovulação → não terminou\n\nApós fecundação → termina","tags":["#AltaRendimento","#CicloMenstrual","#Ginecologia","#Meiose","#Ovulação","Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766775","ankiGuid":"ey/!5O4]i:"},{"id":"anki-ginecologia-ciclo-menstrual-fe33393d1dc2861c","number":"0211b","sourceNumber":"0211b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Assinale a resposta CORRETA:","options":{"A":"Durante a fase folicular, a progesterona suprime a produção do hormônio luteinizante (LH) na adeno-hipófise.","B":"A progesterona torna o endométrio receptivo à nidação. Como efeito secundário, diminui levemente a temperatura basal da mulher.","C":"Designa-se oligomenorreia ciclos regulares com intervalos de 21 dias ou menos.","D":"A inibina é sintetizada pelas células da teca dos folículos ovarianos, tem a ação inibidora específica sobre o GnRH.","E":"A concentração alta de estrógeno inicialmente reduz o pulso de LH e FSH."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":["question_bank/media/ginecologia-ciclo-menstrual/paste-681bfbd5e83f8f9a98fbfeaccb9719d85ec80c56.jpg","question_bank/media/ginecologia-ciclo-menstrual/paste-7406c73e12b6c42b8c9bc3ef3d6afa498e75e390.jpg","question_bank/media/ginecologia-ciclo-menstrual/paste-56501a3038efa7158af084669d4cc8de0acc281b.jpg","question_bank/media/ginecologia-ciclo-menstrual/paste-2a76a41bd79917b808fbbc5fae3026c7c34bb0f5.jpg"],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Ginecologia/Endocrinologia - fisiologia do ciclo menstrual e feedback hormonal).\n\nResumo Essencial\n\nO feedback negativo do estrogênio em concentrações iniciais suprime LH e FSH, mas em concentrações elevadas (pré-ovulatórias) gera feedback positivo desencadeando o pico ovulatório.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"A concentração alta de estrógeno inicialmente reduz o pulso de LH e FSH\":\n\nJustificativa fisiológica:\n\nFase folicular inicial: Estrogênio em concentração moderada → feedback negativo no eixo hipotálamo-hipófise\n\nMecanismo: Inibição da secreção de GnRH → redução de LH/FSH\n\nTransição: Quando estrogênio atinge >200 pg/mL por 48-72h → feedback positivo → pico de LH\n\nErros nas Outras Alternativas ❌\n\nProgesterona diminui temperatura basal:\n\nFalso: Progesterona AUMENTA temperatura basal em 0,3-0,5°C (termogênica)\n\nInibina das células da teca inibe GnRH:\n\nErro duplo: Inibina é produzida pelas células da granulosa e inibe FSH, não GnRH\n\nProgesterona na fase folicular suprime LH:\n\nFalso: Na fase folicular, progesterona está em níveis basais; LH é suprimido pelo estrogênio\n\nOligomenorreia com intervalos ≤21 dias:\n\nDefinição invertida: Oligomenorreia = intervalos >35 dias; ≤21 dias = polimenorreia\n\nFisiologia do Feedback Estrogênico 🔄\n\nConcentração baixa-moderada (<150 pg/mL):\n\nFeedback negativo → ↓ GnRH → ↓ LH/FSH\n\nConcentração alta (>200 pg/mL por 48h):\n\nFeedback positivo → ↑ GnRH → pico de LH → ovulação\n\nAções Hormonais Corretas 📊\n\nProgesterona:\n\nEndométrio: Fase secretória (receptivo à nidação) ✓\n\nTemperatura: AUMENTA temperatura basal ✓\n\nInibina:\n\nOrigem: Células da granulosa ✓\n\nAção: Inibe FSH especificamente ✓\n\nDefinições Menstruais\n\nEumenorreia: 21-35 dias\n\nPolimenorreia: <21 dias\n\nOligomenorreia: >35 dias\n\nAmenorreia: >90 dias\n\nMnemônico Útil ✨\n\n\"Estrogênio = Efeito Escalonado\" (baixo = freia; alto = acelera LH)\n\nAplicação Clínica\n\nAnticoncepcionais: Mantêm estrogênio em nível de feedback negativo\n\nIndução de ovulação: Manipulação do feedback estrogênico\n\nDica: Estrogênio = Dose-dependente! Baixo = freia LH/FSH; Alto = dispara ovulação. Progesterona sempre AUMENTA temperatura! 🌡️📈","tags":["#CicloMenstrual","#Endocrinologia","#Estrógeno","#FeedbackHormonal","#FSH","#Ginecologia","#LH","#Ovulação","Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766776","ankiGuid":"kEh]&-G^)B"},{"id":"anki-ginecologia-ciclo-menstrual-5d169e6a5be7dbe8","number":"0212b","sourceNumber":"0212b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Durante a fase lútea do ciclo menstrual, o aspecto histológico do endométrio é caracterizado como:","options":{"A":"Atrófico.","B":"Secretor.","C":"Proliferativo.","D":"Hiperplásico."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":["question_bank/media/ginecologia-ciclo-menstrual/paste-a1c78337d2b53d5fa72e357927a398742166dcc8.jpg"],"comment":"Classificação da Questão\n\nNível: 🟢 Fácil (Fisiologia básica do ciclo menstrual e histologia endometrial).\n\nResumo Essencial\n\nFase lútea é dominada pela progesterona, que transforma o endométrio em padrão secretor para preparar a implantação embrionária.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"Secretor\":\n\nJustificativa:\n\nFase lútea (pós-ovulatória): Progesterona é o hormônio dominante\n\nProgesterona → Glândulas endometriais tortuosas e dilatadas → Secreção ativa\n\nFunção: Preparar endométrio para implantação (janela de implantação)\n\nErros nas Outras Alternativas ❌\n\nAtrófico:\n\nErro: Ocorre na menopausa ou hipoestrogenia\n\nProliferativo:\n\nErro: Característico da fase folicular (domínio estrogênico)\n\nHiperplásico:\n\nErro: Estado patológico por estímulo estrogênico excessivo\n\nFases do Ciclo Endometrial\n\nFase proliferativa (dias 1-14): Estrogênio → crescimento glandular\n\nFase secretora (dias 15-28): Progesterona → glândulas secretoras\n\nFase menstrual (dias 1-5): Descamação por queda hormonal\n\nTags Temáticas\n\nDica: Fase lútea = Progesterona = Secretor! Lembre-se: estrogênio prolifera, progesterona secreta. 🔄📅","tags":["#CicloMenstrual","#Endocrinologia","#FaseLútea","#FisiologiaFeminina","#Ginecologia","#Histologia","#HistologiaEndometrial","#Progesterona","Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766777","ankiGuid":"DWtk%&up-v"},{"id":"anki-ginecologia-ciclo-menstrual-f26fe63e0fab8e63","number":"0213b","sourceNumber":"0213b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"A respeito da fisiologia do ciclo menstrual, é correto afirmar que:","options":{"A":"A inibina B produz feedback positivo para FSH durante a segunda metade da fase folicular.","B":"Os níveis crescentes de estradiol na fase folicular final fazem feedback positivo para LH.","C":"O estradiol na fase folicular estimula o crescimento endometrial, que na fase folicular final é chamado de secretor.","D":"O endométrio proliferativo, estimulado pela progesterona, apresenta glândulas tortuosas com colabamento dos vasos espiralados."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":["question_bank/media/ginecologia-ciclo-menstrual/paste-159ff29616b075dccbaf96811c42a166cd7107b6.jpg","question_bank/media/ginecologia-ciclo-menstrual/paste-8b7bf7b8a4409054f7786dd807c8a3c88193d2eb.jpg","question_bank/media/ginecologia-ciclo-menstrual/paste-03546b2168d5bb05839e84aab067c31fa46ce285.jpg","question_bank/media/ginecologia-ciclo-menstrual/paste-d39c81874046e7abccf256468263277bda2b2323.jpg"],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Fisiologia do eixo hipotálamo-hipófise-ovariano e ciclo endometrial).\n\nResumo Essencial\n\nPico de estradiol na fase folicular final (pré-ovulatória) induz feedback positivo para LH, desencadeando o pico ovulatório de LH e a ovulação.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"Os níveis crescentes de estradiol na fase folicular final fazem feedback positivo para LH\":\n\nJustificativa:\n\nLimiar crítico: Estradiol >200 pg/mL por >50h → feedback positivo.\n\nMecanismo: Sensibilização dos gonadotrofos hipofisários ao GnRH.\n\nResultado: Pico de LH (24-36h após) → ovulação em ~36h.\n\nFisiologia: Único momento do ciclo com feedback positivo estrogênico.\n\nErros nas Outras Alternativas ❌\n\nEndométrio proliferativo estimulado pela progesterona:\n\nErro: Endométrio proliferativo é estimulado por estradiol, não progesterona.\n\nEndométrio secretor na fase folicular final:\n\nErro: Fase folicular = endométrio proliferativo. Secretor ocorre na fase lútea.\n\nInibina B faz feedback positivo para FSH:\n\nErro: Inibina B faz feedback NEGATIVO para FSH (inibe secreção).\n\nFisiologia do Feedback Estrogênico 🔄\n\nFeedback negativo (maioria do ciclo):\n\nEstradiol baixo-moderado → inibe FSH/LH.\n\nFeedback positivo (fase pré-ovulatória):\n\nEstradiol alto (>200 pg/mL) → estimula pico de LH.\n\nJanela temporal: 48-72h antes da ovulação.\n\nMudanças Endometriais no Ciclo 🔄\n\nFase proliferativa (folicular):\n\nEstímulo: Estradiol.\n\nCaracterísticas: Glândulas retas, estroma compacto.\n\nFase secretora (lútea):\n\nEstímulo: Progesterona + estradiol.\n\nCaracterísticas: Glândulas tortuosas, estroma edematoso.\n\nControle Hormonal 📊\n\nFSH: Inibido por inibina B (feedback negativo).\n\nLH: Estimulado por estradiol alto (feedback positivo pré-ovulatório).\n\nProgesterona: Produzida pelo corpo lúteo pós-ovulação.\n\nCronologia do Ciclo ⏰\n\nDias 1-5: Menstruação (queda hormonal).\n\nDias 6-14: Fase folicular (↑estradiol → ↑endométrio).\n\nDia 14: Ovulação (pico LH).\n\nDias 15-28: Fase lútea (↑progesterona → endométrio secretor).\n\nDica: Estradiol alto (>200 pg/mL) = único feedback POSITIVO do ciclo! Desencadeia pico de LH e ovulação. 🔄⬆️","tags":["#CicloMenstrual","#Estradiol","#FeedbackHormonal","#Ginecologia","#Ovulação","Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766778","ankiGuid":"iZ8.T:Y05"},{"id":"anki-ginecologia-ciclo-menstrual-1a5190e4e2934538","number":"0214b","sourceNumber":"0214b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"No ciclo menstrual, a elevação dos níveis do FSH no final da fase lútea do ciclo anterior tem como função:","options":{"A":"Iniciar a menstruação.","B":"Recrutamento folicular.","C":"Involução do corpo lúteo.","D":"Estímulo à produção de progesterona."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"Resposta Estruturada\n\nClassificação da Questão\n\nNível: 🟡 Média (Fisiologia do ciclo menstrual e mecanismos hormonais específicos).\n\nResumo Essencial\n\nElevação do FSH no final da fase lútea promove recrutamento folicular para o próximo ciclo, iniciando nova coorte de folículos.\n\nCorreção Direta\n\n✅ Alternativa correta: Recrutamento folicular\n\nJustificativa técnica:\n\nQueda de estradiol/progesterona → ↓ feedback negativo → ↑ FSH\n\nFSH elevado estimula coorte folicular a crescer\n\nRecrutamento ocorre nos últimos 5 dias da fase lútea\n\nPreparação para o próximo ciclo ovulatório\n\nErros nas Outras Alternativas ❌\n\nProdução de progesterona: FSH não estimula progesterona (função do LH no corpo lúteo)\n\nInvolução do corpo lúteo: Ocorre por queda do LH e duração limitada (não FSH)\n\nIniciar menstruação: Causada por queda de estradiol/progesterona (não FSH)\n\nFisiologia do Recrutamento 🔬\n\nTiming: Dias 25-28 do ciclo (fase lútea tardia)\n\nMecanismo: FSH → ↑ aromatase → ↑ estradiol → crescimento folicular\n\nJanela FSH: 12-15 folículos são recrutados, mas apenas 1 dominante\n\nSequência Temporal ⚡\n\nCorpo lúteo envelhece → ↓ E2/P4 → ↑ FSH → recrutamento → seleção dominante → ovulação\n\n💡 Dica Ouro: FSH = \"Recrutador folicular\" - sempre que sobe, está chamando novos folículos para competir! 🎯","tags":["#CicloMenstrual","#FisiologiaOvariana","#FSH","#Ginecologia","#RecrutamentoFolicular","Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766779","ankiGuid":"E(3jKOsXP?"},{"id":"anki-ginecologia-ciclo-menstrual-84504d2db1825f82","number":"0215b","sourceNumber":"0215b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Uma pré-pubere tem aproximadamente 400 a 500 mil folículos aptos a recrutamento e ovulação. Na vida intrauterina a população folicular máxima é de aproximadamente:","options":{"A":"2 milhões de folículos com 20 semanas de gestação.","B":"7 milhões de folículos com 40 semanas de gestação.","C":"7 milhões de folículos com 20 semanas de gestação.","D":"700.000 folículos com 40 semanas de gestação."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"Classificação da Questão\n\nNível: 🟡 Média (Embriologia e fisiologia reprodutiva feminina)\n\nResumo Essencial\n\nA população folicular máxima ocorre na vida intrauterina às 20 semanas de gestação com aproximadamente 7 milhões de folículos, seguida de atresia progressiva até o nascimento.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"7 milhões de folículos com 20 semanas de gestação\":\n\nJustificativa:\n\nPico folicular: 20 semanas de gestação = 7 milhões de folículos\n\nProcesso fisiológico: Atresia folicular inicia imediatamente após o pico\n\nAo nascimento: Reduz para ~2 milhões\n\nPré-puberdade: ~400-500 mil (conforme enunciado)\n\nErros nas Outras Alternativas ❌\n\n700.000 folículos com 40 semanas: Número muito baixo para o termo (esperado ~2 milhões)\n\n2 milhões com 20 semanas: Subestima o pico máximo (ocorre 7 milhões)\n\n7 milhões com 40 semanas: Pico já passou - aos 40 semanas há ~2 milhões\n\nCronologia da Reserva Folicular\n\n20 semanas gestação: 7 milhões (pico máximo)\n\nNascimento: ~2 milhões\n\nPuberdade: ~400-500 mil\n\nMenopausa: <1000 folículos\n\nProcesso de Atresia\n\nInício: Logo após o pico de 20 semanas\n\nVelocidade: Constante ao longo da vida\n\nResultado: Perda irreversível de ~1000 folículos/mês\n\nMnemônico Útil ✨\n\n\"20 semanas = 7 Milhões no Máximo!\"\n\nDica: Pico folicular = 20 semanas = 7 milhões! Depois só diminui progressivamente. 🥚📉","tags":["#Embriologia","#FisiologiaReprodutiva","#Ginecologia","#ReservaOvariana","Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766780","ankiGuid":"M-v8}YH,xK"},{"id":"anki-ginecologia-ciclo-menstrual-97691683e7176a20","number":"0216b","sourceNumber":"0216b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Ao exame especular observa-se orifício externo do colo uterino entreaberto com saída de grande quantidade de muco claro e de elevada filância. Possivelmente esta paciente:","options":{"A":"Faz uso de contraceptivo hormonal oral combinado.","B":"Faz uso de progesterona de depósito como contraceptivo.","C":"Deve estar grávida.","D":"Encontra-se no período ovulatório.","E":"Deve estar próxima da menstruação."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":["question_bank/media/ginecologia-ciclo-menstrual/paste-c3eef665bd95568b1a78267213d1b6e16d1e012c.jpg"],"comment":"Classificação da Questão\n\nNível: 🟢 Fácil (Identificação do período fértil pelo muco cervical).\n\nResumo Essencial\n\nMuco cervical claro, filante (elástico) e em grande quantidade é característico do período ovulatório, devido ao pico de estrogênio que aumenta a produção e altera a qualidade do muco para facilitar a migração espermática.\n\nCorreção Direta\n\n✅ Alternativa correta:\n\n\"Encontra-se no período ovulatório\":\n\nJustificativa:\n\nMuco ovulatório:\n\nAspecto: Clara de ovo, filante (>10 cm de elasticidade).\n\nFunção: Lubrificação e transporte de espermatozoides.\n\nOrifício cervical entreaberto: Sinal de ovulação iminente (fase periovulatória).\n\nPor Que Não As Outras Opções? ❌\n\nGravidez:\n\nMuco cervical na gravidez é espesso e opaco (efeito da progesterona).\n\nUso de contraceptivo hormonal combinado:\n\nInibe a ovulação → muco escasso, espesso e não filante.\n\nPróximo da menstruação:\n\nMuco pouco elástico e turbio (fase lútea, dominância de progesterona).\n\nProgesterona de depósito:\n\nEspessa o muco cervical (não há muco claro/filante).\n\nCiclo Menstrual e Muco Cervical\n\nMnemônico Útil ✨\n\n\"Ovulação = Muco em Onda (claro, filante, abundante)\".\n\nAplicação Clínica\n\nMétodo de Billings: Identificação do período fértil pela observação do muco cervical.\n\nInfertilidade: Muco hostil (espesso) pode impedir a passagem de espermatozoides.\n\nDica: Muco claro e elástico = ovulação! Se parece clara de ovo, é sinal de fertilidade. 🥚🔄","tags":["#FisiologiaMenstrual","#Ginecologia","#MucoCervical","#Ovulação","Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766781","ankiGuid":"A3J1Ova@*}"},{"id":"anki-ginecologia-ciclo-menstrual-ea3533c4899f3dd0","number":"0217b","sourceNumber":"0217b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Na mulher os androgênios são sintetizados:","options":{"A":"Nos ovários 50% e nas supra-renais 50%.","B":"Nos ovários, nas supra-renais e no tecido adiposo.","C":"25% nos ovários, 25% nas supra-renais e 50% no tecido adiposo.","D":"Nas supra-renais e no tecido adiposo."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766782","ankiGuid":"EzKhc*P;1T"},{"id":"anki-ginecologia-ciclo-menstrual-94a7690cd27bd6e0","number":"0218b","sourceNumber":"0218b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Os hormônios ovarianos lançados na circulação agem em diferentes níveis do organismo feminino, do cérebro à pele, mas têm a sua principal atuação no trato genital e nas mamas, sendo elas:\nI - Desenvolvimento das estruturas uterinas, da vagina, da vulva e dos ductos mamários;\nII - Ação trófica nos alvéolos mamários;\nIII - Estimulam as alterações secretórias do endométrio. Entre as funções hormonais apresentadas acima, são ações da progesterona as descritas em:","options":{"A":"I e II, apenas.","B":"I e III, apenas.","C":"II e III, apenas.","D":"I, II e III."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766783","ankiGuid":"F@[ok-df3d"},{"id":"anki-ginecologia-ciclo-menstrual-b132fec5e1e177bb","number":"0219b","sourceNumber":"0219b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Durante a fase lútea do ciclo menstrual, observa-se:","options":{"A":"Aumento progressivo de estrogênios, levando à proliferação e espessamento endometrial.","B":"Grande quantidade de progesterona com glândulas endometriais tortuosas e dilatadas.","C":"Aumento sincrônico de FSH e LH, causando isquemia e descamação do endométrio.","D":"Pico de FSH, mantendo o endométrio hipervascularizado e edemaciado.","E":"Pico de LH, promovendo a isquemia das arteríolas espiraladas e descamação endometrial."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766784","ankiGuid":"Iyq-oRE>`>"},{"id":"anki-ginecologia-ciclo-menstrual-0a01e7ea8632f0e1","number":"0220b","sourceNumber":"0220b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Observe os seguintes efeitos hormonais no organismo feminino:\nI - Proliferação endometrial;\nII - Aumento da reabsorção óssea;\nIII - Aumento da espessura da mucosa urinária;\nIV - Pigmentação de aréolas e mamilos. São efeitos decorrentes da ação dos estrogênios o contido APENAS em:","options":{"A":"I, III e IV.","B":"I e IV.","C":"III e IV.","D":"II e III."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766785","ankiGuid":"I|OT=V%HzQ"},{"id":"anki-ginecologia-ciclo-menstrual-4e61e56cdae5e418","number":"0221b","sourceNumber":"0221b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Durante o ciclo menstrual normal há a seleção de um folículo dominante que será ovulado. Sobre o folículo dominante, é INCORRETO dizer:","options":{"A":"Tem maior atividade da enzima aromatase.","B":"Sua seleção ocorre na fase lútea do ciclo.","C":"Tem uma maior produção de estrogênio.","D":"Possui maior número de receptores de FSH."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766786","ankiGuid":"mn-FRug$op"},{"id":"anki-ginecologia-ciclo-menstrual-1db4012ae983f783","number":"0233b","sourceNumber":"0233b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Em relação ao controle neuroendócrino do ciclo menstrual, analise as assertivas abaixo:\nI. Fatores estressores ambientais podem exercer alterações no ciclo menstrual pela ação de neurotransmissores a nível hipotalâmico;\nII. A dopamina e as endorfinas têm efeito inibitório sobre a secreção do GnRH (Hormônio liberador de gonadotrofina);\nIII. A influência do estresse sobre o ciclo menstrual é mediada, principalmente, via secreção de endorfinas.\nQuais estão CORRETAS?","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas I e II.","D":"Apenas II e III.","E":"I, II e III."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766798","ankiGuid":"h)9s1K*(AN"},{"id":"anki-ginecologia-ciclo-menstrual-d5ded495408b08d2","number":"0234b","sourceNumber":"0234b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Para que ocorra a esteroidogênese ovariana, as gonadotrofinas agem nas células do ovário. As gonadotrofinas que agem nas células da teca e da granulosa, respectivamente, são:","options":{"A":"LH e FSH.","B":"GnRH e LH.","C":"FSH e GnRH.","D":"GnRH e FSH."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766799","ankiGuid":"luDg?o>ObS"},{"id":"anki-ginecologia-ciclo-menstrual-d70277fd33398a2c","number":"0235b","sourceNumber":"0235b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Não é efeito do estrogênio:","options":{"A":"Predominância de células superficiais no epitélio vaginal.","B":"Elevação superior à 0,5º C na temperatura corporal basal.","C":"Proliferação endometrial.","D":"Efeito samambaia no muco cervical."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766800","ankiGuid":"DMcwLVbHbV"},{"id":"anki-ginecologia-ciclo-menstrual-1b93eb3b985c2839","number":"0236b","sourceNumber":"0236b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Em relação ao pico ovulatório do LH, é verdadeiro afirmar que os seguintes eventos podem estar associados:\nI – Aumento da produção androgênica pelas células granulosas dos folículos terciários;\nII – Aumento da descamação de células eosinófilas do epitélio estratificado cérvico vaginal;\nIII – Aumento de mucina no muco cervical;\nIV – Aumento da tortuosidade das glândulas do endométrio funcional;\nV – Aumento da androstenodiona nas células tecais de folículos primários recrutados.","options":{"A":"II e V apenas.","B":"III e IV apenas.","C":"I, III e V apenas.","D":"I, III e V apenas.","E":"II, III e IV apenas."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766801","ankiGuid":"eWE]Pd+&gM"},{"id":"anki-ginecologia-ciclo-menstrual-09e8c403f2980149","number":"0237b","sourceNumber":"0237b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"A figura abaixo representa o mecanismo de duas células encontrado no folículo ovariano, principal responsável pela produção esteroides sexuais durante a menacme:","options":{"A":"A célula 1 é célula da camada da granulosa, onde se processa a transformação de colesterol até estrogênios.","B":"A síndrome dos ovários policísticos é caracterizada por níveis suprafisiológicos dos hormônios H-3 e H-4 e relação [ligante “B”]:[ligante “A”] acima de 2 na fase folicular inicial.","C":"Além de estimular a produção esteroidal ovariana, o pico de concentração sérica do ligante “A” ocorre algumas horas antes da ovulação.","D":"O ligante “B” é a gonadotrofina LH, que além de promover a transformação do folículo em corpo lúteo, também estimula a produção de androgênios."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":["question_bank/media/ginecologia-ciclo-menstrual/paste-9f393158763002c3928d46a7a5440cc148447bba.jpg"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766802","ankiGuid":"r^7,&;xMrY"},{"id":"anki-ginecologia-ciclo-menstrual-890204681ba6223a","number":"0238b","sourceNumber":"0238b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"O ciclo menstrual refere-se a um conjunto de alterações fisiológicas que ocorrem no corpo da mulher com uma periodicidade mensal. Assinale a alternativa CORRETA, sobre o ciclo menstrual fisiológico:","options":{"A":"No Hipotálamo, ocorre a liberação de FSH e LH.","B":"Nos anos reprodutivos, a mulher consome cerca de 1.000 folículos a cada ciclo.","C":"À medida que diminui a reserva folicular, os níveis basais de FSH diminuem.","D":"O FSH estimula a produção de androgênios na teca a partir do colesterol.","E":"No endométrio, o estradiol condiciona o aumento do comprimento e da tortuosidade das glândulas e dos vasos espiralados, que se acompanham do incremento na secreção glandular, constituindo a fase secretora."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766803","ankiGuid":"I7QNh8W*79"},{"id":"anki-ginecologia-ciclo-menstrual-a6beb1f2475b14e3","number":"0239b","sourceNumber":"0239b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Os ovários são importantes fontes de andrógenos na mulher. Os principais hormônios androgênicos produzidos por esse órgão são:","options":{"A":"17-OH-progesterona e testosterona.","B":"Testosterona e SDHEA.","C":"Androstenediona e testosterona.","D":"SDHEA e 17-OH-progesterona."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766804","ankiGuid":"G>_]hfDWC!"},{"id":"anki-ginecologia-ciclo-menstrual-5c4061f4ae4e6fb2","number":"0240b","sourceNumber":"0240b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"A ovulação de uma mulher com ciclos menstruais de 30 dias, geralmente acontece:","options":{"A":"Somente quando ela tiver relações sexuais.","B":"Simultaneamente com a menstruação.","C":"14 dias após o início da menstruação.","D":"14 dias antes do início da menstruação."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766805","ankiGuid":"M;8J5k!C@>"},{"id":"anki-ginecologia-ciclo-menstrual-e46c1c0076b8d69d","number":"0241b","sourceNumber":"0241b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Quais são as características hormonais observadas na fase folicular do ciclo menstrual?","options":{"A":"Pulsos de GnRH raros, progesterona alta e estrogênio decrescente.","B":"Pulsos de GnRH raros, progesterona baixa e estrogênio crescente.","C":"Pulsos de GnRH frequentes, progesterona baixa e estrogênio crescente.","D":"Pulsos de GnRH frequentes, progesterona alta e estrogênio alto.","E":"Pulsos de GnRH frequentes, progesterona baixa e estrogênio decrescente."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766806","ankiGuid":"qY{=Y.u*w%"},{"id":"anki-ginecologia-ciclo-menstrual-8a1003430ade99da","number":"0242b","sourceNumber":"0242b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"O ciclo menstrual normal apresenta variações hormonais importantes, conforme apresentado na figura abaixo. Os hormônios apresentados por números de 1 a 4 representam respectivamente:","options":{"A":"FSH, Estradiol, Progesterona e LH.","B":"LH, FSH, Estradiol e Progesterona.","C":"Estradiol, FSH, LH e Progesterona.","D":"Progesterona, Estradiol, LH e FSH."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":["question_bank/media/ginecologia-ciclo-menstrual/paste-44c54f9f2a59e60325129a2e5ac430d28cb470bb.jpg"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766807","ankiGuid":"sCU5EotoVL"},{"id":"anki-ginecologia-ciclo-menstrual-9e7a3e4a65366856","number":"0243b","sourceNumber":"0243b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Importante mecanismo de regulação do ciclo ovulatório são as interações endocrinológicas entre os diversos órgãos femininos. Nesse caso, assinale a alternativa que apresenta o MELHOR exemplo de feedback de alça longa.","options":{"A":"Hipotálamo-hipófise.","B":"Tireoide-ovário.","C":"Ovário-hipófise.","D":"Endométrio-hipófise."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766808","ankiGuid":"tr(F`*d.>j"},{"id":"anki-ginecologia-ciclo-menstrual-7c50cdda379e1562","number":"0244b","sourceNumber":"0244b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Durante a vida embrionária, a mulher produz uma grande quantidade de folículos ovarianos, que interrompem sua evolução em um determinado estágio e retornam ao seu desenvolvimento na puberdade, por meio da estimulação gonadotrófica. Levando em consideração os estágios evolutivos da foliculogênese, em qual etapa do desenvolvimento celular ocorre a parada da maturação?","options":{"A":"Telófase da mitose.","B":"Anáfase da meiose.","C":"Metáfase da mitose.","D":"Prófase da meiose.","E":"Diacinese da prófase I."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766809","ankiGuid":"pSzqzRENK%"},{"id":"anki-ginecologia-ciclo-menstrual-3bd740685234bcac","number":"0245b","sourceNumber":"0245b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Durante o ciclo ovulatório ocorrem sistemas de retroalimentação entre os esteroides sexuais e as gonadotrofinas. Nesse contexto, o estrogênio no meio do ciclo em altas concentrações:","options":{"A":"Provoca retrocontrole positivo sobre FSH.","B":"Provoca retrocontrole negativo sobre LH e FSH.","C":"Não provoca nenhum retrocontrole sobre LH e FSH.","D":"Provoca retrocontrole positivo sobre LH."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766810","ankiGuid":"Q2*@7P^}=+"},{"id":"anki-ginecologia-ciclo-menstrual-8008ffcbe8a08874","number":"0246b","sourceNumber":"0246b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Em relação à fisiologia do ciclo menstrual normal, assinale a alternativa ERRADA:","options":{"A":"A inibina A é secretada pelo corpo lúteo.","B":"A variabilidade da fase folicular é responsável pelas alterações da duração total do ciclo.","C":"A variação dos níveis de progesterona após a ovulação contraindica sua dosagem como sinal presumido de ovulação.","D":"Os extremos da vida reprodutiva são caracterizados por ciclos anovulatórios e/ou irregulares."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766811","ankiGuid":"ntf#ZfkD9N"},{"id":"anki-ginecologia-ciclo-menstrual-76250cd1b0f5f4bc","number":"0247b","sourceNumber":"0247b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Sobre o ciclo reprodutivo feminino analise as assertivas e marque a alternativa CORRETA:\n\nI. O GnRH (Hormônio Liberador de Gonadotrofina) é sintetizado pelas células neurossecretoras do hipotálamo.\n\nII. O GnRH é transportado pelo sistema porta hipofisário para o lobo anterior da hipófise.\n\nIII. O GnRH estimula a adenohipófise a produzir FSH (Hormônio Folículo-estimulante) e LH (Hormônio Luteinizante).\n\nIV. O FSH estimula o desenvolvimento dos folículos ovarianos e a produção de estrogênio.\n\nV. O LH atua liberando o oócito secundário, e estimula as células foliculares e o corpo lúteo a produzirem progesterona.","options":{"A":"Somente as afirmativas I, II e III estão corretas.","B":"Somente as afirmativas II e IV estão corretas.","C":"Somente as afirmativas I, III e V estão corretas.","D":"Somente as afirmativas I, II, III e IV estão corretas.","E":"Todas as afirmativas estão corretas."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766812","ankiGuid":"Hu}O~@AI?P"},{"id":"anki-ginecologia-ciclo-menstrual-6936138df9aef691","number":"0248b","sourceNumber":"0248b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Em uma mulher de 20 anos, com ciclos menstruais regulares de 28 dias, no momento sem vida sexual ativa, episódios de sangramento que ocorrem ao redor do 13º dia do ciclo podem ser decorrentes de:","options":{"A":"Queda do nível sérico de estrogênio.","B":"Aumento do FSH.","C":"Queda dos níveis séricos da progesterona.","D":"Aumento do LH."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766813","ankiGuid":"hke?#_EKH="},{"id":"anki-ginecologia-ciclo-menstrual-def6fc2e9f30b586","number":"0249b","sourceNumber":"0249b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Em relação à foliculogênese no ciclo menstrual, analise as assertivas abaixo, assinalando V, se Verdadeiras, ou F, se Falsas.\n\n( ) Os folículos primordiais são dependentes das gonadotrofinas.\n\n( ) A atresia folicular é o evento predominante no ovário.\n\n( ) O Hormônio Luteinizante (LH) estimula a síntese de androgênios nas células da teca.\n\n( ) O Hormônio Folículo Estimulante (FSH) estimula a síntese de estrogênios nas células da granulosa.\n\n( ) O FSH controla a função lútea após a ovulação do folículo dominante. A ordem correta de preenchimento dos parênteses, de cima para baixo, é:","options":{"A":"F – V – V – V – F.","B":"V – F – V – F – F.","C":"V – F – V – V – V.","D":"F – F – F – V – V.","E":"F – F – V – F – F."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766814","ankiGuid":"q;79Wl1I!{"},{"id":"anki-ginecologia-ciclo-menstrual-4bfd2f812e459643","number":"0250b","sourceNumber":"0250b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Paciente de 56 anos de idade queixou-se ao médico ginecologista de secura vaginal, desconforto, prurido e dispareunia nas relações sexuais. Menopausa aos 49 anos de idade e nunca usou terapia hormonal no período do climatério por não apresentar fogachos. Realizou seus exames de rotina, em que apresentou citologia hormonal de Papanicolaou com alteração. A alteração celular esperada nesse exame é a perda das células:","options":{"A":"Superficiais vaginais.","B":"Da basal interna vaginal.","C":"Da basal externa vaginal.","D":"Da basal interna e externa vaginal.","E":"Da camada intermediária vaginal."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740837766815","ankiGuid":"Rf^:6Z?h;<"},{"id":"anki-ginecologia-ciclo-menstrual-cdfcd2dc86700ac9","number":"0222b","sourceNumber":"0222b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Sobre a fisiologia menstrual e o controle neuroendócrino do ciclo, assinale a alternativa CORRETA:","options":{"A":"Altos níveis de estrogênio aumentam a síntese e armazenamento de FSH e LH , tendo, portanto, importante efeito na regulação de LH e FSH .","B":"O pulso de secreção de GnRH deve estar dentro de um patamar crítico de frequência, e não de concentração, para manter a função reprodutiva normal.","C":"O aumento da frequência de pulso de GnRH aumenta a secreção de FSH , já a diminuição do pulso de GnRH aumenta a secreção de LH .","D":"O GnRH tem ação na glândula hipófise anterior, atuando na síntese, armazenamento, ativação e secreção de gonadotropinas."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740871925634","ankiGuid":"Wz&ZI!|$8"},{"id":"anki-ginecologia-ciclo-menstrual-17c0f4f9058e37dc","number":"0223b","sourceNumber":"0223b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Mulher, 30 anos de idade, hígida, com ciclos menstruais normais, observam-se no 8º dia do ciclo as seguintes ações fisiológicas, exceto.","options":{"A":"LH em elevação.","B":"FSH em declinio.","C":"Endométrio proliferativo.","D":"Citologia vaginal com predomínio de células eosinófilas acidófilas.","E":"Quantidade aumentada de estradiol produzido nas células da teca de folículos primários."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740872301304","ankiGuid":"d6LxZQ7h`l"},{"id":"anki-ginecologia-ciclo-menstrual-94c641769be1ac71","number":"0224b","sourceNumber":"0224b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Na fisiologia do ciclo menstrual, o pico do LH se mantém por","options":{"A":"24 a 36 horas","B":"10 a 12 horas","C":"24 a 48 horas","D":"48 a 50 horas"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740872333514","ankiGuid":"o;[Z_3_qo:"},{"id":"anki-ginecologia-ciclo-menstrual-f0036a56ad15e727","number":"0225b","sourceNumber":"0225b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Em se tratando de fisiologia ginecológica e reprodutiva é correto afirmar, EXCETO:","options":{"A":"A ocitocina produzida pela adeno-hipófise promove a contração da rede de células mioepiteliais que envolve os ácinos mamários.","B":"O hormônio liberador de gonadotrofinas (GnRH ), disponibilizado de forma pulsátil pelo hipotálamo, controla a secreção de LH e de FSH .","C":"A secreção de prolactina é influenciada pela secreção hipotalâmica de dopamina.","D":"Na puberdade, somente 300.000 dos 6 a 7 milhões de oócitos originais estarão disponíveis para o processo da ovulação."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740872387035","ankiGuid":"i!JziM2L@n"},{"id":"anki-ginecologia-ciclo-menstrual-470b281c11ab881b","number":"0226b","sourceNumber":"0226b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Em meninas recém-nascidas, os oócitos encontram-se na:","options":{"A":"Prófase da primeira divisão meiótica.","B":"Metáfase da primeira divisão meiótica.","C":"Anáfase da primeira divisão meiótica.","D":"Telófase da primeira divisão meiótica."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740872416376","ankiGuid":"vcpb;=w(7z"},{"id":"anki-ginecologia-ciclo-menstrual-b8a72ff578a4bb4c","number":"0227b","sourceNumber":"0227b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"O ciclo menstrual pode ser dividido em dois segmentos: o ciclo ovariano e o ciclo uterino.\nConsiderando, respectivamente, a primeira fase de ambos os ciclos, poderíamos denominá-las de fases:","options":{"A":"folicular e lútea.","B":"secretora e folicular.","C":"proliferativa e secretora.","D":"folicular e proliferativa."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740872456802","ankiGuid":"p{goq:I]N2"},{"id":"anki-ginecologia-ciclo-menstrual-6c726bef720061c4","number":"0228b","sourceNumber":"0228b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Em relação ao ciclo menstrual, assinale a alternativa INCORRETA:","options":{"A":"O ciclo é dividido em duas fases: folicular e lútea, sendo que a fase folicular começa com o início da menstruação e termina no dia anterior ao aumento do H ormônio Luteinizante (LH ) e a fase lútea começa no dia do pico de LH e termina no início da próxima menstruação.","B":"As concentrações séricas de H ormônio Folículo-Estimulante (FSH ) e LH estão diminuindo nesse momento (fase folicular tardia) devido aos efeitos de feedback negativo do estradiol e talvez de outros hormônios liberados pelo ovário.","C":"O aumento das concentrações séricas de estradiol resulta na proliferação do endométrio uterino, que se torna mais espesso, com um aumento no número de glândulas e o desenvolvimento de um padrão de \"tripla faixa\" ao ultrassom.","D":"O H ormônio Antimülleriano (H AM) sérico tem sido usado como um potencial marcador de saúde e envelhecimento ovariano, secretado por pequenos folículos antrais, se correlaciona com o número total desses folículos ovarianos e apresenta grande variabilidade ao longo do ciclo menstrual."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740872498339","ankiGuid":"Js-GAy`##+"},{"id":"anki-ginecologia-ciclo-menstrual-4ff46a0cd3980a0b","number":"0229b","sourceNumber":"0229b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Em relação à Bsiologia do ciclo menstrual e endometrial. Qual hormônio tem seu pico na fase endometrial secretória (segunda fase)?","options":{"A":"Progesterona","B":"Estrogênio","C":"FSH","D":"LH"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740872536046","ankiGuid":"P4Ws-rlI=$"},{"id":"anki-ginecologia-ciclo-menstrual-396b2def937795b2","number":"0230b","sourceNumber":"0230b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"No ciclo menstrual, a ocorrência de gravidez levará à produção de gonadotroBna coriônica humana, cuja função é sustentar a produção hormonal do corpo lúteo. Caso a gravidez não aconteça, a falência do corpo lúteo determina queda de estrogênio e progesterona que dará início a eventos endometriais importantes que culminarão com a menstruação. Em relação à menstruação, assinale a alternativa INCORRETA.","options":{"A":"A camada funcional do endométrio sofrerá ação de enzimas como as metaloproteinases e fosfatase ácida que promovem sua digestão.","B":"Alterações vasomotoras rítmicas nas arteríolas espiraladas levam à isquemia e descamação endometrial.","C":"Na fase isquêmica do ciclo menstrual observa-se aumento na liberação de prostaglandinas.","D":"A progesterona tem papel importante em controlar o sangramento menstrual ao promover a proliferação e regeneração rápida do endométrio.","E":"Com a ruptura endotelial e perda sanguínea, entram em jogo mecanismos de coagulação e angiogênese."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740872589702","ankiGuid":"rBUboNYjzy"},{"id":"anki-ginecologia-ciclo-menstrual-87ecbd4e23f9a4c4","number":"0231b","sourceNumber":"0231b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"Mulher com ciclos menstruais regulares, não usuária de anticoncepção, não grávida, realiza biópsia endometrial no vigésimo segundo dia do ciclo menstrual. O resultado mais provável do anatomopatológico é:","options":{"A":"Endométrio proliferativo.","B":"Endométrio atrófico.","C":"Endométrio misto.","D":"Endométrio secretor."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740872624601","ankiGuid":"O`R0>|Pfvc"},{"id":"anki-ginecologia-ciclo-menstrual-c65d61b397b4d077","number":"0232b","sourceNumber":"0232b","collectionBlock":"anki:ginecologia-ciclo-menstrual","collectionLabel":"Anki · Ciclo Menstrual","documentBlock":"","area":"Ginecologia","specialty":"Ginecologia","topic":"Ciclo Menstrual","subtopic":"","stem":"O processo de proliferação endometrial tem como hormônio diretamente relacionado:","options":{"A":"estrógeno","B":"progesterona","C":"androstenediona","D":"FSH"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Ciclo Menstrual","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia","Ciclo Menstrual","Anki"],"ankiNoteId":"1740955501563","ankiGuid":"n.*B9ioAFc"}]};
